def taller_within(a: list[int], k: int) -> list[int]:
    if k == 0:
        return [0] * len(a)

    ranks = {height: i + 1 for i, height in enumerate(sorted(set(a)))}
    size = len(ranks)
    bit = [0] * (size + 1)
    result = []

    for i, height in enumerate(a):
        if i > k:
            rank = ranks[a[i - k - 1]]
            while rank <= size:
                bit[rank] -= 1
                rank += rank & -rank

        rank = ranks[height]
        count_le = 0
        while rank:
            count_le += bit[rank]
            rank -= rank & -rank

        result.append(min(i, k) - count_le)

        rank = ranks[height]
        while rank <= size:
            bit[rank] += 1
            rank += rank & -rank

    return result
